"""voice.py: turn an unvoiced lesson article (as published in the Vol 5 page) into a voiced one.

Usage: python3 voice.py LESSON_DIR AID PAGE_IN
LESSON_DIR holds head.md, replaces.md, body.md, texts.py (T dict), V2.py/V3.py and V2.out/V3.out.
Writes LESSON_DIR/AID.article.html and LESSON_DIR/AID.zxt.json. The page splice is done by splice.py.
"""
import html, json, os, re, subprocess, sys, ast
import markdown

KX = "/home/claude/kx"
FIXED = {  # kind -> (label, header text is the title?)
    "plain": (None, False), "math": (None, False), "check": (None, False), "predict": (None, False),
    "read": (None, False), "broken": (None, False),
    "worked": ("Worked example", True), "visual": ("See it drawn", True),
    "practice": ("Industry practice", True), "recap": ("Recap", True),
}

# ---------- math ----------
def katex_batch(items):
    if not items:
        return []
    js = ("const k=require('katex');let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{"
          "const a=JSON.parse(d);process.stdout.write(JSON.stringify(a.map(([s,disp])=>"
          "k.renderToString(s,{displayMode:disp,output:'html',throwOnError:false}))))})")
    r = subprocess.run(["node", "-e", js], input=json.dumps(items), capture_output=True, text=True, cwd=KX)
    if r.returncode:
        raise SystemExit(r.stderr)
    return json.loads(r.stdout)

def protect_math(md, store):
    def disp(m):
        store.append((m.group(1).strip(), True)); return f"\x00M{len(store)-1}\x00"
    def inl(m):
        store.append((m.group(1), False)); return f"\x00M{len(store)-1}\x00"
    md = re.sub(r"\$\$(.+?)\$\$", disp, md, flags=re.S)
    md = re.sub(r"(?<![\w\\$])\$(?=\S)([^$\n]+?)(?<=\S)\$(?!\d)", inl, md)
    return md

# ---------- markdown ----------
def code_html(code, lang):
    return ('<div class="code"><button type="button" class="copy" aria-label="Copy code">Copy</button>'
            f'<pre><code class="language-{lang}">{html.escape(code, quote=True)}</code></pre></div>')

def md_to_html(md, ctx, inline=False):
    """Markdown with fenced code, tables, $math$, check marks. ctx: dict with code files and outputs."""
    blocks = []
    def fence(m):
        lang, flag, body = (m.group(1) or "plaintext"), m.group(2) or "", m.group(3)
        body = re.sub(r"\{\{(\w+)\}\}", lambda x: ctx[x.group(1)], body)
        h = code_html(body if body.endswith("\n") else body + "\n", lang)
        if flag.strip() == "run":
            key = m.group(3).strip().strip("{}")
            out = ctx.get(key + ".out")
            if out is not None:
                h += ('\n<aside class="co co-run"><div class="co-label">What you should see</div><div class="co-body">'
                      + code_html(out, "plaintext") + '</div></aside>')
        blocks.append(h)
        return f"\n\n\x00B{len(blocks)-1}\x00\n\n"
    md = re.sub(r"(?m)^```(\w+)?([ \t]+\w+)?\n(.*?)\n```[ \t]*$", fence, md, flags=re.S)
    md = re.sub(r"\{\{(\w+)\}\}", lambda x: ctx[x.group(1)].strip(), md)
    store = []
    md = protect_math(md, store)
    out = markdown.markdown(md, extensions=["tables", "sane_lists"], output_format="html")
    rendered = katex_batch(store)
    def put_math(m):
        i = int(m.group(1)); h = rendered[i]
        return f'<div class="kx">{h}</div>' if store[i][1] else h
    out = re.sub(r"\x00M(\d+)\x00", put_math, out)
    out = re.sub(r"<p>\x00B(\d+)\x00</p>", lambda m: blocks[int(m.group(1))], out)
    out = re.sub(r"\x00B(\d+)\x00", lambda m: blocks[int(m.group(1))], out)
    out = out.replace("<table>", '<div class="tbl"><table>').replace("</table>", "</table></div>")
    out = out.replace("<li>✗", '<li><span class="ck-no" aria-label="Wrong">✗</span>')
    out = re.sub(r"<br />\s*✓", '<br />\n  <span class="ck-yes" aria-label="Right">✓</span>', out)
    if inline:
        out = re.sub(r"^<p>(.*)</p>$", r"\1", out.strip(), flags=re.S)
    return out

def callouts(md, ctx):
    """Render a directive body: ':::kind header' ... ':::' boxes, '??? sol | title' details, plain markdown between."""
    parts, pos = [], 0
    pat = re.compile(r"(?ms)^:::(\w+)[ \t]*(.*?)\n(.*?)\n:::[ \t]*$|^\?\?\? sol \| (.*?)\n(.*?)\n\?\?\?[ \t]*$")
    qa = ctx.setdefault("_qa", [0])
    for m in pat.finditer(md):
        pre = md[pos:m.start()].strip()
        if pre:
            parts.append(md_to_html(pre, ctx))
        if m.group(1):
            kind, head, body = m.group(1), m.group(2).strip(), m.group(3)
            label, has_title = FIXED[kind]
            h = f'<aside class="co co-{kind}"><div class="co-label">{html.escape(label if has_title else head)}</div>'
            if has_title and head:
                h += f'<div class="co-title">{md_to_html(head, ctx, inline=True)}</div>'
            h += f'<div class="co-body">{md_to_html(body, ctx)}</div></aside>'
        else:
            qa[0] += 1
            h = (f'<details class="qa" id="{ctx["_aid"]}-qa{qa[0]}"><summary><span class="qa-lvl qa-sol">Solution</span>'
                 f'<span class="qa-q">{md_to_html(m.group(4).strip(), ctx, inline=True)}</span></summary>'
                 f'<div class="qa-a">{md_to_html(m.group(5), ctx)}</div></details>')
        parts.append(h)
        pos = m.end()
    rest = md[pos:].strip()
    if rest:
        parts.append(md_to_html(rest, ctx))
    return "\n".join(parts)

# ---------- main.py in parts ----------
def mainpy_parts(src, budget=75):
    tree = ast.parse(src)
    lines = src.split("\n")
    nodes = [n for n in tree.body if not (isinstance(n, ast.If) and "__name__" in ast.unparse(n.test))]
    groups, cur, cur_start = [], [], 1
    for i, n in enumerate(nodes):
        end = n.end_lineno
        if cur and end - cur_start + 1 > budget:
            groups.append(cur); cur = []; cur_start = start_of(n, lines)
        cur.append(n)
    if cur:
        groups.append(cur)
    out = []
    for gi, g in enumerate(groups):
        a = 1 if gi == 0 else start_of(g[0], lines)
        b = g[-1].end_lineno
        code = "\n".join(lines[a-1:b]).strip("\n") + "\n"
        names = [n.name for n in g if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)) and n.name != "main"]
        out.append((names, code))
    return out

def start_of(n, lines):
    s = n.lineno
    if getattr(n, "decorator_list", None):
        s = min(d.lineno for d in n.decorator_list)
    while s > 1 and lines[s-2].startswith("#"):   # keep comments directly above
        s -= 1
    return s

def mainpy_html(lesson_code_dir, py, main_out):
    src = open(os.path.join(lesson_code_dir, "main.py")).read()
    parts = mainpy_parts(src)
    n = len(parts) + 1
    h = ['<p>The whole of <code>code/main.py</code> follows in parts. Each part runs on this page, in order, in one Python '
         'session; the last part does what <code>python3 code/main.py</code> does.</p>']
    for i, (names, code) in enumerate(parts, 1):
        lab = ", ".join(f"<code>{html.escape(x)}</code>" for x in names) or "setup"
        h.append(f'<p><strong>Part {i} of {n} · {lab}</strong></p>\n' + code_html(code, "python") + "\n")
    h.append(f'<p><strong>Part {n} of {n} · run it</strong> (what <code>python3 code/main.py</code> does)</p>\n'
             + code_html("main()\n", "python")
             + '\n<aside class="co co-run"><div class="co-label">What you should see</div><div class="co-body">'
             + code_html(main_out, "plaintext") + "</div></aside>")
    return "\n".join(h)

def frag(text, ctx):
    """The HTML an existing paragraph or run of list items renders to, without its outer <p>/<ul>."""
    lines = [x for x in text.strip("\n").split("\n") if x.strip()]
    if all(re.match(r"\s*([-*]|\d+\.) ", x) for x in lines):
        return "</li>\n<li>".join(md_to_html(re.sub(r"^\s*([-*]|\d+\.) ", "", x), ctx, inline=True) for x in lines)
    return md_to_html(text.strip(), ctx, inline=True)

# ---------- article surgery ----------
def h2_positions(art):
    return [(m.start(), m.end(), html.unescape(re.sub(r"<[^>]+>", "", m.group(1)))) for m in re.finditer(r"<h2>(.*?)</h2>", art)]

def section_end(art, heading):
    hs = h2_positions(art)
    for i, (s, e, t) in enumerate(hs):
        if t == heading:
            if i + 1 < len(hs):
                return hs[i+1][0]
            j = art.find('<aside class="co co-checked">', e)
            return j if j != -1 else art.find("</div><p class=\"src-credit\">", e)
    raise SystemExit(f"heading not found: {heading!r}; have {[t for *_, t in hs]}")

def after_heading(art, heading):
    for s, e, t in h2_positions(art):
        if t == heading:
            return e
    raise SystemExit(f"heading not found: {heading!r}")

def before_heading(art, heading):
    hs = h2_positions(art)
    for i, (s, e, t) in enumerate(hs):
        if t == heading:
            if heading == "Ship it" and i and hs[i-1][2] == "Practice and reference":
                return hs[i-1][0]
            return s
    raise SystemExit(f"heading not found: {heading!r}")

def insert(art, pos, h):
    return art[:pos] + "\n" + h + "\n" + art[pos:]

def main():
    d, aid, page = sys.argv[1], sys.argv[2], sys.argv[3]
    t = open(page).read()
    m = re.search(rf'<article class="module" id="{aid}".*?</article>', t, re.S)
    art = m.group(0)
    T = {}
    exec(open(os.path.join(d, "texts.py")).read(), {}, ns := {})
    T = ns["T"]
    ctx = {"_aid": aid}
    ctx.update(T)
    for v in ("V2", "V3", "V4"):
        p = os.path.join(d, v + ".py")
        if os.path.exists(p):
            ctx[v] = open(p).read().rstrip("\n")
            ctx[v + ".out"] = open(os.path.join(d, v + ".out")).read()
    spec = "\n".join(open(os.path.join(d, f)).read() for f in ("head.md", "replaces.md", "body.md") if os.path.exists(os.path.join(d, f)))
    dirs = re.findall(r"(?ms)^@@(\w+)[ \t]*(.*?)\n(.*?)^@@[ \t]*$", spec)
    zxt = {}
    code_dir = json.load(open(os.path.join(d, "meta.json")))["code_dir"]
    # repair a truncated "The idea in one line" box from the source blockquote (a cut in the original page build)
    doc = os.path.join(os.path.dirname(code_dir), "docs", "en.md")
    if os.path.exists(doc):
        bq = next((ln[2:] for ln in open(doc).read().splitlines() if ln.startswith("> ")), None)
        m = re.search(r'(The idea in one line</div><div class="co-body"><p>)(.*?)(</p>)', art, re.S)
        if bq and m:
            ph = aid[1:3].lstrip("0")   # "(Lesson N)" appears on the page as a link to aPPNN
            bq = re.sub(r"\(Lesson (\d+)\)", lambda x: f'(<a href="#a{aid[1:3]}{int(x.group(1)):02d}">Lesson {ph}.{int(x.group(1))}</a>)', bq)
            full = frag(bq, ctx)
            if full != m.group(2) and full.startswith(m.group(2)) and len(m.group(2)) > 40:
                art = art[:m.start(2)] + full + art[m.end(2):]
    for kind, arg, body in dirs:
        arg = arg.strip()
        if kind == "replace":
            old, new = body.split("\n===\n")
            o_h, n_h = frag(old, ctx), frag(new, ctx)
            if o_h not in art:
                raise SystemExit(f"replace target not found:\n{o_h}")
            art = art.replace(o_h, n_h, 1)
        elif kind == "top":
            art = insert(art, after_heading(art, arg), callouts(body, ctx))
        elif kind == "end":
            art = insert(art, section_end(art, arg), callouts(body, ctx))
        elif kind == "before":
            art = insert(art, before_heading(art, arg), callouts(body, ctx))
        elif kind == "mainpy":
            out = open(os.path.join(d, "main.out")).read()
            art = insert(art, section_end(art, arg or "Build it"), mainpy_html(code_dir, None, out))
        elif kind == "takeaways":
            for ln in body.strip().split("\n"):
                k, v = ln.split(" | ", 1)
                zxt[k.strip()] = v.strip()
        else:
            raise SystemExit("unknown directive " + kind)
    art = re.sub(r"(by Rohit Ghumare \(MIT licence\)), in this course's format, with its code run and its interview questions attached\.",
                 r"\1, with worked examples, exercises and takeaways added for this course.", art)
    heads = [t for *_, t in h2_positions(art)]
    missing = [h for h in heads if h not in zxt and h not in ("Practice and reference", "Ship it", "Exercises", "Interview questions")]
    extra = [k for k in zxt if k not in heads]
    if missing or extra:
        raise SystemExit(f"takeaways mismatch: missing {missing}, extra {extra}")
    open(os.path.join(d, aid + ".article.html"), "w").write(art)
    json.dump(zxt, open(os.path.join(d, aid + ".zxt.json"), "w"), ensure_ascii=False)
    print(f"{aid}: article {len(m.group(0))} -> {len(art)} bytes; headings {heads}")

if __name__ == "__main__":
    main()

