# The lesson's ToM agent and trial (imported from main.py), with the parts separated: the "preference prime"
# that run_trial gives ToM agents before turn 0, and the belief model itself. 200 trials per row, as in the
# lesson; runs in about a second.
import random
from main import World, Agent, run_trial

def trial(n_agents, n_boxes, tom, prime, seed, max_turns=10, convention=False):
    """run_trial's loop, with the prime made optional and an optional fixed convention (agent i takes box i)."""
    rng = random.Random(seed); world = World.new(n_boxes)
    agents = [Agent(f"agent-{i}", tom=tom) for i in range(n_agents)]
    if prime:
        for i, a in enumerate(agents):
            for j, other in enumerate(agents):
                if i != j:
                    a.observe(other.name, j % n_boxes)
    dup = turns = 0
    for t in range(max_turns):
        turns = t + 1; commit = {}
        for i, a in enumerate(agents):
            if a.collected:
                continue
            if convention and t == 0 and i % n_boxes in world.boxes_with_tokens:
                c = i % n_boxes
            else:
                c = a.choose_target(world, rng)
            if c >= 0:
                commit[a.name] = c
        for o in agents:
            for other, box in commit.items():
                if other != o.name:
                    o.observe(other, box)
        ch = list(commit.values()); dup += sum(ch.count(b) - 1 for b in set(ch))
        taken = set()
        for name, box in commit.items():
            if box not in taken and box in world.boxes_with_tokens:
                world.boxes_with_tokens.discard(box); taken.add(box)
                next(a for a in agents if a.name == name).collected = True
        if all(a.collected for a in agents):
            break
    return sum(a.collected for a in agents), dup, turns

def bench(label, **kw):
    rs = [trial(seed=s, **kw) for s in range(200)]
    n = kw["n_agents"]
    print(f"   {label:44s} full {sum(r[0] == n for r in rs):3d}/200  collisions/trial {sum(r[1] for r in rs) / 200:.2f}"
          f"  turns {sum(r[2] for r in rs) / 200:.2f}")

check = [run_trial(3, 3, True, s) for s in range(200)]
print(f"1. the lesson's ToM run reproduced: collisions/trial {sum(c[1] for c in check) / 200:.2f}")
bench("zeroth-order", n_agents=3, n_boxes=3, tom=False, prime=False)
bench("first-order ToM with the prime (the lesson)", n_agents=3, n_boxes=3, tom=True, prime=True)
bench("first-order ToM without the prime", n_agents=3, n_boxes=3, tom=True, prime=False)
bench("no ToM, fixed convention: agent i takes box i", n_agents=3, n_boxes=3, tom=False, prime=False, convention=True)
print("   the prime tells agent i that each other agent j 'prefers' box j, which leaves only box i")

print("\n2. scaling up, as exercise 1 asks")
for n in (5, 10):
    bench(f"{n} agents, {n} boxes, zeroth-order", n_agents=n, n_boxes=n, tom=False, prime=False)
    bench(f"{n} agents, {n} boxes, ToM without the prime", n_agents=n, n_boxes=n, tom=True, prime=False)
    bench(f"{n} agents, {n} boxes, ToM with the prime", n_agents=n, n_boxes=n, tom=True, prime=True)

print("\n3. what the belief model remembers")
a = Agent("agent-0", tom=True)
for t, boxes in enumerate([(3, 4), (2, 1), (1, 2), (2, 1)]):
    a.observe("agent-1", boxes[0]); a.observe("agent-2", boxes[1])
w = World.new(5)
window = a.observations[-(len(w.boxes_with_tokens) + 2):]
print(f"   with 5 boxes it looks back over the last {len(window)} observations: {window}")
print("   that is 3 turns of 2 agents plus half of an older turn: the window is set by the number of boxes left, not by turns or agents")

