# The lesson's code is TypeScript, so this block rebuilds two of its checks in Python and runs them on real-shaped
# A2A 1.0 data: a task-state machine that validates a stream of status updates, and skill selection from Agent Cards
# by tag and input type. The transition table follows the lesson's diagram, treats AUTH_REQUIRED like INPUT_REQUIRED,
# allows cancel or failure while waiting, and lets a stream open in WORKING as the lesson's SSE example does.
# Runs in under a second.
TERMINAL = {"TASK_STATE_COMPLETED", "TASK_STATE_FAILED", "TASK_STATE_CANCELED", "TASK_STATE_REJECTED"}
NEXT = {"TASK_STATE_SUBMITTED": {"TASK_STATE_WORKING", "TASK_STATE_REJECTED", "TASK_STATE_CANCELED"},
        "TASK_STATE_WORKING": {"TASK_STATE_WORKING", "TASK_STATE_INPUT_REQUIRED", "TASK_STATE_AUTH_REQUIRED",
                               "TASK_STATE_COMPLETED", "TASK_STATE_FAILED", "TASK_STATE_CANCELED"},
        "TASK_STATE_INPUT_REQUIRED": {"TASK_STATE_WORKING", "TASK_STATE_CANCELED", "TASK_STATE_FAILED"},
        "TASK_STATE_AUTH_REQUIRED": {"TASK_STATE_WORKING", "TASK_STATE_CANCELED", "TASK_STATE_FAILED"}}
def check(stream):
    state, problems = None, []
    for i, ev in enumerate(stream, 1):
        s = ev["status"]["state"]
        if state in TERMINAL:
            problems.append(f"event {i}: {s} after terminal {state}")
        elif state is None:
            if s not in ("TASK_STATE_SUBMITTED", "TASK_STATE_WORKING"):
                problems.append(f"event {i}: task cannot start in {s}")
        elif s not in NEXT.get(state, set()):
            problems.append(f"event {i}: {state} -> {s} is not a legal move")
        state = s if not (state in TERMINAL) else state
    return problems or ["valid"]
ev = lambda s: {"taskId": "task-123", "contextId": "ctx-123", "status": {"state": s}}
STREAMS = {"the lesson's stream": [ev("TASK_STATE_WORKING"), ev("TASK_STATE_WORKING"), ev("TASK_STATE_COMPLETED")],
           "asks for input, then finishes": [ev("TASK_STATE_SUBMITTED"), ev("TASK_STATE_WORKING"), ev("TASK_STATE_INPUT_REQUIRED"),
                                             ev("TASK_STATE_WORKING"), ev("TASK_STATE_COMPLETED")],
           "update after completion": [ev("TASK_STATE_WORKING"), ev("TASK_STATE_COMPLETED"), ev("TASK_STATE_WORKING")],
           "rejected while working": [ev("TASK_STATE_SUBMITTED"), ev("TASK_STATE_WORKING"), ev("TASK_STATE_REJECTED")],
           "no prefix (pre-1.0 spelling)": [ev("submitted"), ev("working"), ev("completed")]}
print("1. validating task status streams")
for name, stream in STREAMS.items():
    print(f"   {name:<32} {'; '.join(check(stream))}")

CARDS = [
    {"name": "Research Agent", "defaultInputModes": ["text/plain", "application/json"], "skills": [
        {"id": "web-research", "tags": ["research", "search", "summarization"]},
        {"id": "doc-analysis", "tags": ["docs", "analysis"], "inputModes": ["text/plain", "application/pdf"]}]},
    {"name": "Code Review Agent", "defaultInputModes": ["text/plain"], "skills": [
        {"id": "review-python", "tags": ["code", "review", "python"]}]},
    {"name": "Data Agent", "defaultInputModes": ["text/csv", "application/json"], "skills": [
        {"id": "sql-report", "tags": ["sql", "report", "analysis"]}]},
]
def pick(tags, mime):
    best = []
    for card in CARDS:
        for sk in card["skills"]:
            modes = sk.get("inputModes", card["defaultInputModes"])
            score = len(set(tags) & set(sk["tags"]))
            if score and mime in modes:
                best.append((score, card["name"], sk["id"]))
    return max(best)[1:] if best else ("no agent", "-")
print("\n2. choosing a skill from Agent Cards (tags must overlap and the input type must be accepted)")
for tags, mime in ((["research", "summarization"], "text/plain"), (["analysis"], "application/pdf"),
                   (["analysis"], "text/csv"), (["review", "python"], "application/pdf"), (["translation"], "text/plain")):
    print(f"   tags {tags}, input {mime:<16} -> {pick(tags, mime)}")

