"""embed.py PAGE_IN Z2A_HTML PAGE_OUT: copy Zero to Agents lessons into Vol 5 as companions, unchanged in content."""
import json, re, sys, html
src, z2a_path, dst = sys.argv[1:4]
t, z = open(src).read(), open(z2a_path).read()
Z2A = "https://claude.ai/artifact/HnQQ11kd6iyjw5nE5Au8U6"
PLAN = {"ph-14": [f"l06{i:02d}" for i in range(1, 26)] + [f"l07{i:02d}" for i in range(1, 13)] + ["l0903"]
                 + [f"l12{i:02d}" for i in range(1, 21)],
        "ph-15": [f"l10{i:02d}" for i in range(1, 6)],
        "ph-16": [f"l08{i:02d}" for i in range(1, 6)]}
PHASE_NAME = {"ph-14": "Phase 14 · Agent Engineering", "ph-15": "Phase 15 · Autonomous Systems", "ph-16": "Phase 16 · Multi-Agent &amp; Swarms"}

def course(text):
    m = re.search(r"(const COURSE = )(\[.*?\])(;\n)", text, re.S)
    return m, json.loads(m.group(2))
mz, CZ = course(z)
zinfo = {l["id"]: l for p in CZ for ch in p["chapters"] for l in ch["lessons"]}
mv, CV = course(t)

def articles(text):
    pos = [(m.start(), m.group(1)) for m in re.finditer(r'<article class="module" id="([\w-]+)"', text)]
    out = {}
    for i, (s, a) in enumerate(pos):
        e = text.find("</article>", s) + len("</article>")
        out[a] = (s, e)
    return out
zart = articles(z)
present = set(articles(t)) | {a for ids in PLAN.values() for a in ids}

def transform(a, phase):
    s, e = zart[a]; h = z[s:e]
    h = re.sub(r'(<nav class="crumbs"[^>]*>.*?<span aria-hidden="true">/</span>)<a href="#ch-\d+">[^<]*</a>',
               lambda m: m.group(1) + f'<a href="#{phase}">{PHASE_NAME[phase]}</a>', h, count=1, flags=re.S)
    h = h.replace('<div class="m-meta"><span class="chip chip-num">', '<div class="m-meta"><span class="chip chip-zero">From Zero to Agents</span><span class="chip chip-num">', 1)
    def link(m):
        target = m.group(1)
        if target in present:
            return m.group(0)
        return f'href="{Z2A}#{target}" target="_blank" rel="noopener"'
    body_start = h.find("</header>")
    foot = h.find('<footer class="m-foot">')
    mid = re.sub(r'href="#((?:l\d{4})|(?:ch-\d+)|(?:cs-[\w-]+))"', link, h[body_start:foot])
    return h[:body_start] + mid + h[foot:]

def label(lid, info):
    return f'{info["num"]} · {info["title"]}' if info.get("num") and not lid.startswith("cs-") else info["title"]

all_lessons = []
for p in CV:
    for ch in p["chapters"]:
        for l in ch["lessons"]:
            all_lessons.append((ch["id"], l))
vinfo = {l["id"]: l for _, l in all_lessons}

new_html = {}
for phase, ids in PLAN.items():
    ch = next(c for p in CV for c in p["chapters"] if c["id"] == phase)
    last = ch["lessons"][-1]["id"]
    for a in ids:
        zi = zinfo[a]
        ch["lessons"].append({"id": a, "num": zi["num"], "title": zi["title"], "min": zi["min"],
                              "depth": "From Zero to Agents", "paths": ["A"]})
        new_html[a] = transform(a, phase)
    vart = articles(t)
    s, e = vart[last]
    t = t[:e] + "".join(new_html[a] for a in ids) + t[e:]

# footer prev/next for every article whose neighbours changed
order = [l for p in CV for ch in p["chapters"] for l in ch["lessons"]]
info = {l["id"]: l for l in order}
def pn_row(i):
    parts = []
    if i > 0:
        p = order[i - 1]
        parts.append(f'<a class="pn prev" href="#{p["id"]}"><span class="pn-dir">Previous</span><span class="pn-t">{label(p["id"], p)}</span></a>')
    if i + 1 < len(order):
        n = order[i + 1]
        parts.append(f'<a class="pn next" href="#{n["id"]}"><span class="pn-dir">Next</span><span class="pn-t">{label(n["id"], n)}</span></a>')
    return '<div class="pn-row">' + "".join(parts) + "</div>"
touched = set(new_html)
for phase, ids in PLAN.items():
    i0 = next(i for i, l in enumerate(order) if l["id"] == ids[0])
    touched |= {order[i0 - 1]["id"], order[min(i0 + len(ids), len(order) - 1)]["id"]}
fixed = 0
for i, l in enumerate(order):
    if l["id"] not in touched:
        continue
    vart = articles(t)
    if l["id"] not in vart:
        continue
    s, e = vart[l["id"]]; h = t[s:e]
    h2 = re.sub(r'<div class="pn-row">.*?</div>(?=</footer>)', pn_row(i), h, count=1, flags=re.S)
    if h2 != h:
        fixed += 1
    t = t[:s] + h2 + t[e:]
mv = re.search(r"(const COURSE = )(\[.*?\])(;\n)", t, re.S)
t = t[:mv.start(2)] + json.dumps(CV, ensure_ascii=False) + t[mv.end(2):]
imgs = sorted({i for h in new_html.values() for i in re.findall(r'src="(img/[^"]+)"', h)})
json.dump(imgs, open(dst + ".imgs.json", "w"))
open(dst, "w").write(t)
print(f"embedded {len(new_html)} lessons, footers rewritten {fixed}, images {len(imgs)}, size {len(t)//1024} KB")

