# The lesson's bargaining simulator (imported from main.py), checked on what its deal-rate benchmark hides:
# what each side's opening offer reads, why OG-Narrator still fails one deal in nine, and who keeps the surplus.
# Runs in about a second.
import random
from main import BargainState, naive_llm_bargain, og_narrator_bargain, seller_response, simulate_bargain

print("1. what the OG buyer's opening offer is computed from")
for smin in (50, 60, 70):
    s = BargainState(buyer_max=100, seller_min=smin)
    print(f"   buyer's max 100, seller's private min {smin} -> OG buyer opens at {og_narrator_bargain(s, None)}")
print("   the opening moves with the seller's private minimum: the buyer reads the other side's reservation price")
s = BargainState(buyer_max=100, seller_min=60)
s.buyer_offer = og_narrator_bargain(s, None)
s.seller_offer = seller_response(s, None)
print(f"   one run: buyer opens {s.buyer_offer}, seller replies {s.seller_offer}, so the deal closes at {s.buyer_offer} "
      f"in round 1; the seller would have taken anything from 60")

def bargain(buyer_fn, rng, bmax, smin, max_rounds=5, seller_fn=seller_response):
    """The loop of main.simulate_bargain, returning the price too."""
    s = BargainState(buyer_max=bmax, seller_min=smin, max_rounds=max_rounds)
    while s.rounds < s.max_rounds:
        s.buyer_offer = buyer_fn(s, rng)
        if s.seller_offer is not None and s.buyer_offer >= s.seller_offer:
            return s.seller_offer if smin <= s.seller_offer <= bmax else None
        s.seller_offer = seller_fn(s, rng)
        if s.seller_offer <= s.buyer_offer:
            return s.buyer_offer if smin <= s.buyer_offer <= bmax else None
        s.rounds += 1
    return None

def bench(buyer_fn, max_rounds=5, seller_fn=seller_response, trials=1000):
    rng = random.Random(42); deals, share = 0, []
    for _ in range(trials):
        smin = rng.randint(50, 80); bmax = rng.randint(max(smin + 5, 75), 115)
        p = bargain(buyer_fn, rng, bmax, smin, max_rounds, seller_fn)
        if p is not None:
            deals += 1; share.append((bmax - p) / (bmax - smin))
    return deals / trials, sum(share) / len(share)

print("\n2. deal rate and the buyer's share of the surplus, (max - price) / (max - min)")
for name, fn in (("naive LLM", naive_llm_bargain), ("OG-Narrator", og_narrator_bargain)):
    d, sh = bench(fn)
    print(f"   {name:12s} deal rate {d:.1%}, buyer keeps {sh:.0%} of the surplus")
print("   (a zone of agreement exists in every trial: max is at least min + 5)")

print("\n3. why OG-Narrator misses: rounds")
for r in (5, 8, 12):
    print(f"   max_rounds {r:2d}: OG-Narrator deal rate {bench(og_narrator_bargain, r)[0]:.1%}")

print("\n4. no peeking: both sides open from their own value only")
def blind_seller(s, rng):
    if s.seller_offer is None:
        return s.seller_min + 40                     # own value plus a fixed margin
    return seller_response(s, rng)
def blind_buyer(s, rng):
    if s.buyer_offer is None:
        return s.buyer_max - 30
    return og_narrator_bargain(s, rng)
for r in (5, 12):
    d, sh = bench(blind_buyer, r, blind_seller)
    print(f"   max_rounds {r:2d}: deal rate {d:.1%}, buyer keeps {sh:.0%} of the surplus")

