# The lesson's Lead and Worker (imported from main.py) with workers that misbehave the way real ones do: one raises,
# one is five times slower than the rest. Then the same plan run by a lead that sets a timeout and reports what is
# missing. Simulated fetches take 0.3 s (the lesson's) and 1.5 s (the slow one). Runs in about 4 seconds.
import threading, time
import main
from main import Lead, Trace, WorkerResult

real_fetch = main.fake_web_fetch
def flaky_fetch(query):
    if "open problems" in query:
        raise ConnectionError("search API returned 503")
    if "state of the art" in query:
        time.sleep(1.5)
        return f"Summary for '{query}': 3 key findings from 5 sources."
    return real_fetch(query)
main.fake_web_fetch = flaky_fetch
import io, contextlib
with contextlib.redirect_stderr(io.StringIO()):       # the failing thread prints a traceback; keep the output readable
    answer, stats = Lead(Trace()).run("What changed in multi-agent systems 2023 to 2026?")
print("1. the lesson's Lead with one failing and one slow worker")
print(f"   wall clock {stats['wall_clock_seconds']} s (waits for the slowest); workers planned {stats['worker_count']}")
print(f"   sections in the answer: {answer.count(chr(10) + '- ')} of 3, and nothing in it says one is missing")

class CarefulLead(Lead):
    def run(self, query, timeout=0.6):
        t0 = time.time()
        subs = self.plan(query)
        results, errors = [None] * len(subs), {}
        def work(i, sq):
            try:
                results[i] = WorkerResult(sq, main.fake_web_fetch(sq), 800, 0.0)
            except Exception as e:
                errors[i] = f"{type(e).__name__}: {e}"
        threads = [threading.Thread(target=work, args=(i, sq), daemon=True) for i, sq in enumerate(subs)]
        for th in threads: th.start()
        deadline = t0 + timeout
        for th in threads: th.join(max(0.0, deadline - time.time()))
        lines = []
        for i, sq in enumerate(subs):
            topic = sq.split(" -- ")[1]
            if results[i]: lines.append(f"   - {topic}: ok")
            elif i in errors: lines.append(f"   - {topic}: MISSING ({errors[i]})")
            else: lines.append(f"   - {topic}: MISSING (no result within {timeout} s)")
        return lines, round(time.time() - t0, 2)
lines, wall = CarefulLead(Trace()).run("What changed in multi-agent systems 2023 to 2026?")
print(f"\n2. a lead with a 0.6 s deadline that reports gaps: wall clock {wall} s")
print("\n".join(lines))
main.fake_web_fetch = real_fetch

